#!/usr/bin/env node
/* One script for a page: src/household, standard/engine, standard/intake, the schema, the law, the recipes and the dictionary, as window.KittyHousehold.
   build.py concatenates by string replace, so this stays that simple: walk the requires, wrap each file, no transforms, no dependencies. The page
   takes dist/kitty-household.js with one .replace when it is ready to.
     node tools/household-bundle.js [--out path]
     node tools/household-bundle.js --defaults    refresh src/household/defaults.json from the standard, after node standard/world/build.js */
"use strict";
const fs = require("fs"), path = require("path"), zlib = require("zlib");

const root = path.join(__dirname, ".."), ENTRY = "src/household/browser.js";
const posix = (p) => p.split(path.sep).join("/");
function resolve(from, spec) {
  if (spec === "kitty:recipes") return spec;
  if (!spec.startsWith(".")) return null;
  const base = path.join(root, path.dirname(from), spec);
  for (const c of [base, `${base}.js`, `${base}.json`, path.join(base, "index.js")]) if (fs.existsSync(c) && fs.statSync(c).isFile()) return posix(path.relative(root, c));
  return null;
}
function collect() {
  const mods = new Map(), todo = [ENTRY];
  while (todo.length) {
    const id = todo.pop();
    if (mods.has(id)) continue;
    if (id === "kitty:recipes") {
      const dir = path.join(root, "standard", "recipes");
      mods.set(id, { source: `module.exports = [${fs.readdirSync(dir).filter((f) => f.endsWith(".json")).sort().map((f) => JSON.stringify(JSON.parse(fs.readFileSync(path.join(dir, f), "utf8")))).join(",")}];`, map: {} });
      continue;
    }
    const text = fs.readFileSync(path.join(root, id), "utf8");
    if (id.endsWith(".json")) { mods.set(id, { source: `module.exports = ${JSON.stringify(JSON.parse(text))};`, map: {} }); continue; }
    const map = {};
    for (const m of text.matchAll(/require\("([^"]+)"\)/g)) { const to = resolve(id, m[1]); if (to) { map[m[1]] = to; todo.push(to); } }
    mods.set(id, { source: text.replace(/^#!.*\n/, ""), map });
  }
  return mods;
}
function bundle() {
  const mods = collect(), ids = [...mods.keys()].sort();
  const body = ids.map((id) => { const m = mods.get(id); return `${JSON.stringify(id)}: [${JSON.stringify(m.map)}, function (module, exports, require) {\n${m.source}\n}]`; }).join(",\n");
  const text = `/* The Kitty household runtime. Generated by tools/household-bundle.js; do not edit. ${ids.length} modules. */
(function (root) {
"use strict";
const defs = {\n${body}\n};
const cache = {};
function load(id) {
  if (cache[id]) return cache[id].exports;
  const def = defs[id], module = (cache[id] = { exports: {} });
  def[1](module, module.exports, (spec) => { const to = def[0][spec]; if (!to) throw new Error("This host has no " + spec); return load(to); });
  return module.exports;
}
root.KittyHousehold = load(${JSON.stringify(ENTRY)});
})(typeof self !== "undefined" ? self : globalThis);
`;
  // Safe to inline in any page, whatever charset it is served with: a raw ellipsis read as windows-1252 changes the words a household stores.
  const ascii = text.replace(/[^\x00-\x7f]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, "0")}`);
  return { text: ascii.replace(/<\/script/gi, "<\\/script"), modules: ids.length };
}
// Shared data the standard has no file for yet (finding R-009), and the day the law was read (R-003). A test fails when this goes stale.
function writeDefaults() {
  const world = path.join(root, "standard", ".build", "world", "setup"), json = (p) => JSON.parse(fs.readFileSync(p, "utf8"));
  const clean = (r) => Object.fromEntries(Object.entries(r).filter(([, v]) => v !== null && v !== undefined && v !== ""));
  const about = json(path.join(root, "src", "household", "defaults.json"))._about;
  const out = { _about: about, reference_verified_at: json(path.join(root, "standard", "reference", "au-verified.json")).verified_at, categories: json(path.join(world, "category.json")).map(clean), tax_map: json(path.join(world, "tax_map.json")).map(clean) };
  fs.writeFileSync(path.join(root, "src", "household", "defaults.json"), `${JSON.stringify(out, null, 1)}\n`);
  console.log(`src/household/defaults.json: ${out.categories.length} categories, ${out.tax_map.length} tax map rows.`);
}
if (require.main === module && process.argv.includes("--defaults")) writeDefaults();
else if (require.main === module) {
  const i = process.argv.indexOf("--out"), out = i > 0 ? process.argv[i + 1] : path.join(root, "dist", "kitty-household.js");
  const { text, modules } = bundle();
  new Function(text);
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, text);
  console.log(`${path.relative(process.cwd(), out)}: ${modules} modules, ${Buffer.byteLength(text)} bytes, ${zlib.gzipSync(text).length} gzipped.`);
}
module.exports = { bundle };
